/*
 * qnx_compat.h - generated by QNX Integration Advisor for motor-pid-controller.
 * Contains only the shims this repository needs:
 *   - qnx_periodic_timer_*: timerfd-like periodic timer (QNX: timer_create + pulse)
 * Licensed under Apache-2.0.
 */
#ifndef QNX_COMPAT_H
#define QNX_COMPAT_H

#include <errno.h>
#include <stdint.h>
#include <time.h>
#include <unistd.h>

#ifdef __QNX__
#include <sys/neutrino.h>
#include <sys/siginfo.h>

#ifdef _NTO_CHF_PRIVATE
#define QNX_COMPAT_CHF _NTO_CHF_PRIVATE
#else
#define QNX_COMPAT_CHF 0
#endif

#define QNX_COMPAT_PULSE_TIMER   (_PULSE_CODE_MINAVAIL + 0)
#endif /* __QNX__ */

/* ------------------------------------------------------------------ periodic timer */
typedef struct {
#ifdef __QNX__
    int     chid;
    int     coid;
    timer_t timer;
#else
    int     fd;
#endif
} qnx_periodic_timer_t;

#ifdef __QNX__
static inline int qnx_periodic_timer_create(qnx_periodic_timer_t *t, uint64_t period_ns, int pulse_prio)
{
    struct sigevent   ev;
    struct itimerspec its;

    t->chid = ChannelCreate(QNX_COMPAT_CHF);
    if (t->chid == -1)
        return -1;
    t->coid = ConnectAttach(0, 0, t->chid, _NTO_SIDE_CHANNEL, 0);
    if (t->coid == -1) {
        ChannelDestroy(t->chid);
        return -1;
    }
    SIGEV_PULSE_INIT(&ev, t->coid, pulse_prio, QNX_COMPAT_PULSE_TIMER, 0);
    if (timer_create(CLOCK_MONOTONIC, &ev, &t->timer) == -1) {
        ConnectDetach(t->coid);
        ChannelDestroy(t->chid);
        return -1;
    }
    its.it_value.tv_sec  = (time_t)(period_ns / 1000000000ULL);
    its.it_value.tv_nsec = (long)(period_ns % 1000000000ULL);
    its.it_interval      = its.it_value;
    if (timer_settime(t->timer, 0, &its, NULL) == -1) {
        timer_delete(t->timer);
        ConnectDetach(t->coid);
        ChannelDestroy(t->chid);
        return -1;
    }
    return 0;
}

/* Blocks until the next period. Other pulses on this private channel are ignored. */
static inline int qnx_periodic_timer_wait(qnx_periodic_timer_t *t)
{
    struct _pulse p;
    for (;;) {
        if (MsgReceivePulse(t->chid, &p, sizeof p, NULL) == -1)
            return -1;
        if (p.code == QNX_COMPAT_PULSE_TIMER)
            return 0;
    }
}

static inline void qnx_periodic_timer_destroy(qnx_periodic_timer_t *t)
{
    timer_delete(t->timer);
    ConnectDetach(t->coid);
    ChannelDestroy(t->chid);
}
#else  /* Linux and other POSIX hosts keep the original timerfd behaviour */
#include <sys/timerfd.h>
static inline int qnx_periodic_timer_create(qnx_periodic_timer_t *t, uint64_t period_ns, int pulse_prio)
{
    struct itimerspec its;
    (void)pulse_prio;
    t->fd = timerfd_create(CLOCK_MONOTONIC, 0);
    if (t->fd == -1)
        return -1;
    its.it_value.tv_sec  = (time_t)(period_ns / 1000000000ULL);
    its.it_value.tv_nsec = (long)(period_ns % 1000000000ULL);
    its.it_interval      = its.it_value;
    return timerfd_settime(t->fd, 0, &its, NULL);
}

static inline int qnx_periodic_timer_wait(qnx_periodic_timer_t *t)
{
    uint64_t exp;
    return read(t->fd, &exp, sizeof exp) == (ssize_t)sizeof exp ? 0 : -1;
}

static inline void qnx_periodic_timer_destroy(qnx_periodic_timer_t *t)
{
    close(t->fd);
}
#endif

#endif /* QNX_COMPAT_H */

/*
 * qnx_motor_pid_resmgr.c - single-threaded QNX 8.0 resource manager skeleton at /dev/motor_pid.
 * Generated by QNX Integration Advisor for motor-pid-controller. Apache-2.0.
 *
 *   read()   -> text status line
 *   write()  -> sets an integer value (e.g. a setpoint)
 *   devctl() -> DCMD_MOTOR_PID_GET_STATUS / DCMD_MOTOR_PID_SET_VALUE (motor_pid_dcmd.h)
 *   periodic timer pulse (pulse_attach) -> tick_handler(), where the repo's loop body goes
 *
 * Build:  qcc -Vgcc_ntox86_64 -Wall -Wextra -Werror -Iinclude -Isrc -o motor_pid_resmgr src/qnx_motor_pid_resmgr.c
 * Run:    motor_pid_resmgr -p 1 -u 1000 &      (starts as root, drops to uid 1000)
 */
#include <errno.h>
#include <fcntl.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#include <devctl.h>
#include <sys/iofunc.h>
#include <sys/dispatch.h>
#include <sys/neutrino.h>
#include <sys/procmgr.h>
#include <sys/stat.h>

#include "motor_pid_dcmd.h"

typedef struct {
    /* TODO: embed the repository's main state (pid_ctrl_t from src/pid.h) here. */
    motor_pid_status_t status;
} service_state_t;

static service_state_t        state;
static resmgr_connect_funcs_t connect_funcs;
static resmgr_io_funcs_t      io_funcs;
static iofunc_attr_t          dev_attr;
static char                   read_buf[128];

/* ------------------------------------------------------------------ read() */
static int io_read(resmgr_context_t *ctp, io_read_t *msg, RESMGR_OCB_T *ocb)
{
    int status = iofunc_read_verify(ctp, msg, ocb, NULL);
    if (status != EOK)
        return status;
    if ((msg->i.xtype & _IO_XTYPE_MASK) != _IO_XTYPE_NONE)
        return ENOSYS;

    if (ocb->offset == 0) {
        int n = snprintf(read_buf, sizeof read_buf, "value=%d ticks=%llu\n",
                         (int)state.status.value, (unsigned long long)state.status.ticks);
        if (n < 0)
            return EIO;
    }
    size_t len = strlen(read_buf);
    size_t nbytes = 0;
    if (ocb->offset >= 0 && (size_t)ocb->offset < len) {
        nbytes = len - (size_t)ocb->offset;
        if (nbytes > (size_t)_IO_READ_GET_NBYTES(msg))
            nbytes = (size_t)_IO_READ_GET_NBYTES(msg);
    }
    _IO_SET_READ_NBYTES(ctp, nbytes);
    if (nbytes == 0)
        return _RESMGR_NPARTS(0);
    SETIOV(ctp->iov, read_buf + ocb->offset, nbytes);
    ocb->offset += (off_t)nbytes;
    ocb->attr->flags |= IOFUNC_ATTR_ATIME;
    return _RESMGR_NPARTS(1);
}

/* ------------------------------------------------------------------ write() */
static int io_write(resmgr_context_t *ctp, io_write_t *msg, RESMGR_OCB_T *ocb)
{
    int status = iofunc_write_verify(ctp, msg, ocb, NULL);
    if (status != EOK)
        return status;
    if ((msg->i.xtype & _IO_XTYPE_MASK) != _IO_XTYPE_NONE)
        return ENOSYS;

    size_t nbytes = (size_t)_IO_WRITE_GET_NBYTES(msg);
    char   buf[32];
    size_t want = nbytes < sizeof buf - 1 ? nbytes : sizeof buf - 1;
    ssize_t got = resmgr_msgread(ctp, buf, want, sizeof msg->i);
    if (got == -1)
        return errno;
    buf[got] = '\0';
    state.status.value = (int32_t)strtol(buf, NULL, 10);   /* TODO: parse the repo's command format */

    _IO_SET_WRITE_NBYTES(ctp, nbytes);
    if (nbytes > 0)
        ocb->attr->flags |= IOFUNC_ATTR_MTIME | IOFUNC_ATTR_CTIME;
    return EOK;
}

/* ------------------------------------------------------------------ devctl() */
static int io_devctl(resmgr_context_t *ctp, io_devctl_t *msg, RESMGR_OCB_T *ocb)
{
    int status = iofunc_devctl_default(ctp, msg, ocb);
    if (status != _RESMGR_DEFAULT)
        return status;

    void  *data = _DEVCTL_DATA(msg->i);
    size_t nbytes = 0;

    switch (msg->i.dcmd) {
    case DCMD_MOTOR_PID_GET_STATUS:
        if (msg->i.nbytes < sizeof(state.status))
            return EINVAL;
        memcpy(data, &state.status, sizeof(state.status));
        nbytes = sizeof(state.status);
        break;
    case DCMD_MOTOR_PID_SET_VALUE: {
        int32_t v;
        if (msg->i.nbytes < sizeof v)
            return EINVAL;
        if (resmgr_msgread(ctp, &v, sizeof v, sizeof msg->i) != (ssize_t)sizeof v)
            return EFAULT;
        state.status.value = v;
        break;
    }
    default:
        return ENOSYS;
    }

    memset(&msg->o, 0, sizeof msg->o);
    msg->o.ret_val = EOK;
    msg->o.nbytes = (uint32_t)nbytes;
    return _RESMGR_PTR(ctp, &msg->o, sizeof msg->o + nbytes);
}

/* ------------------------------------------------------------------ timer pulse */
static int tick_handler(message_context_t *ctp, int code, unsigned flags, void *handle)
{
    (void)ctp; (void)code; (void)flags; (void)handle;
    state.status.ticks++;
    /* TODO: move the body of motor-pid-controller's periodic loop here
       (read inputs, compute, write outputs). It runs in the resmgr's single thread,
       so it is serialized with client requests and needs no extra locking. */
    return 0;
}

static int drop_privileges(uid_t uid)
{
    /* Path registration is done. Deny and lock every ability for the non-root domain,
       then become that user. */
    int rc = procmgr_ability(0, PROCMGR_ADN_NONROOT | PROCMGR_AOP_DENY | PROCMGR_AOP_LOCK | PROCMGR_AID_EOL);
    if (rc != EOK) {
        fprintf(stderr, "procmgr_ability: %s\n", strerror(rc));
        return -1;
    }
    if (setgid((gid_t)uid) == -1 || setuid(uid) == -1) {
        perror("setuid");
        return -1;
    }
    return 0;
}

int main(int argc, char **argv)
{
    long period_ms = 1;
    long run_uid = -1;
    int  opt;
    while ((opt = getopt(argc, argv, "p:u:")) != -1) {
        switch (opt) {
        case 'p': period_ms = strtol(optarg, NULL, 10); break;
        case 'u': run_uid = strtol(optarg, NULL, 10); break;
        default:
            fprintf(stderr, "usage: %s [-p period_ms] [-u uid]\n", argv[0]);
            return EXIT_FAILURE;
        }
    }
    if (period_ms <= 0)
        period_ms = 1;

    dispatch_t *dpp = dispatch_create();
    if (dpp == NULL) {
        perror("dispatch_create");
        return EXIT_FAILURE;
    }

    resmgr_attr_t rattr;
    memset(&rattr, 0, sizeof rattr);
    rattr.nparts_max = 1;
    rattr.msg_max_size = 2048;

    iofunc_func_init(_RESMGR_CONNECT_NFUNCS, &connect_funcs, _RESMGR_IO_NFUNCS, &io_funcs);
    io_funcs.read = io_read;
    io_funcs.write = io_write;
    io_funcs.devctl = io_devctl;
    iofunc_attr_init(&dev_attr, S_IFCHR | 0666, NULL, NULL);

    if (resmgr_attach(dpp, &rattr, "/dev/motor_pid", _FTYPE_ANY, 0, &connect_funcs, &io_funcs, &dev_attr) == -1) {
        perror("resmgr_attach /dev/motor_pid");
        return EXIT_FAILURE;
    }

    int code = pulse_attach(dpp, MSG_FLAG_ALLOC_PULSE, 0, tick_handler, NULL);
    if (code == -1) {
        perror("pulse_attach");
        return EXIT_FAILURE;
    }
    int coid = message_connect(dpp, MSG_FLAG_SIDE_CHANNEL);
    if (coid == -1) {
        perror("message_connect");
        return EXIT_FAILURE;
    }
    struct sigevent ev;
    SIGEV_PULSE_INIT(&ev, coid, 21, code, 0);
    timer_t timer;
    if (timer_create(CLOCK_MONOTONIC, &ev, &timer) == -1) {
        perror("timer_create");
        return EXIT_FAILURE;
    }
    struct itimerspec its;
    its.it_value.tv_sec = period_ms / 1000;
    its.it_value.tv_nsec = (period_ms % 1000) * 1000000L;
    its.it_interval = its.it_value;
    if (timer_settime(timer, 0, &its, NULL) == -1) {
        perror("timer_settime");
        return EXIT_FAILURE;
    }

    if (run_uid >= 0 && drop_privileges((uid_t)run_uid) != 0)
        return EXIT_FAILURE;

    dispatch_context_t *ctp = dispatch_context_alloc(dpp);
    if (ctp == NULL) {
        perror("dispatch_context_alloc");
        return EXIT_FAILURE;
    }
    for (;;) {
        dispatch_context_t *next = dispatch_block(ctp);
        if (next == NULL) {
            if (errno == EINTR)
                continue;
            perror("dispatch_block");
            return EXIT_FAILURE;
        }
        ctp = next;
        dispatch_handler(ctp);
    }
}

