struct pollfd pfd[2] = {
    { .fd = tfd, .events = POLLIN },
    { .fd = cfd, .events = POLLIN },
};
int n = poll(pfd, 2, -1);
if (n > 0 && (pfd[0].revents & POLLIN)) {
    /* periodic work */
}
```

